def number_to_words(n: int) -> str:
    if not 0 <= n <= 999999:
        raise ValueError("number out of range")

    if n == 0:
        return "zero"

    ones = [
        "", "one", "two", "three", "four", "five",
        "six", "seven", "eight", "nine"
    ]
    teens = [
        "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty",
        "sixty", "seventy", "eighty", "ninety"
    ]

    def under_100(num: int) -> str:
        if num < 10:
            return ones[num]
        if num < 20:
            return teens[num - 10]
        t, o = divmod(num, 10)
        if o == 0:
            return tens[t]
        return f"{tens[t]}-{ones[o]}"

    def under_1000(num: int) -> str:
        h, rem = divmod(num, 100)
        parts = []
        if h:
            parts.append(f"{ones[h]} hundred")
        if rem:
            parts.append(under_100(rem))
        return " ".join(parts)

    thousands, rem = divmod(n, 1000)
    parts = []
    if thousands:
        parts.append(f"{under_1000(thousands)} thousand")
    if rem:
        parts.append(under_1000(rem))

    return " ".join(parts)
